#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <sched.h>
#include <errno.h>
#include <string.h>

void *thread_func(void *arg) {
    printf("\nThread is running.\n");
    // Do work here
    return NULL;
}

int main() {
    pthread_t thread;
    int ret;
    int policy = SCHED_FIFO; 
    struct sched_param param;

    // Determine acceptable priority range for SCHED_FIFO
    int min_prio = sched_get_priority_min(policy);
    int max_prio = sched_get_priority_max(policy);

    if (min_prio == -1 || max_prio == -1) {
        perror("sched_get_priority range failed");
        return 1;
    }

    // Set a high priority (requires elevated privileges to succeed)
    param.sched_priority = max_prio > 10 ? max_prio - 5 : max_prio;

    printf("Creating thread and attempting to set real-time policy (%s) with priority %d.\n", 
           policy == SCHED_FIFO ? "SCHED_FIFO" : "Unknown", param.sched_priority);

    if (pthread_create(&thread, NULL, thread_func, NULL) != 0) {
        perror("pthread_create failed");
        return 1;
    }

    // Attempt to set the scheduling parameters
    ret = pthread_setschedparam(thread, policy, &param);
    if (ret != 0) {
        fprintf(stderr, "\n[WARNING] pthread_setschedparam failed (Error %d: %s).\n", ret, strerror(ret));
        if (ret == EPERM) {
            fprintf(stderr, "\tThis usually means the process lacks necessary capabilities (e.g., CAP_SYS_NICE).\n");
        }
    } else {
        printf("Successfully set scheduling parameters.\n");
    }

    // Verify the current settings
    int retrieved_policy;
    struct sched_param retrieved_param;
    if (pthread_getschedparam(thread, &retrieved_policy, &retrieved_param) == 0) {
        printf("Verification: Current Policy=%s, Priority=%d\n", 
               retrieved_policy == SCHED_FIFO ? "SCHED_FIFO" : (retrieved_policy == SCHED_OTHER ? "SCHED_OTHER" : "Other"), 
               retrieved_param.sched_priority);
    } else {
        perror("pthread_getschedparam failed");
    }

    pthread_join(thread, NULL);

    return 0;
}
